const atlas=typeof Image==='undefined'?{}:new Image();atlas.src='art/activities.png';
export const illustratedActivities=['garden','pig','chicken','tarot','live','tea','bake','paint','sew','recycle','incense','fish','chant','beads','meditate','sweep','meal','prostrate','sermon'];
export function drawIllustratedActivity(view){if(!atlas.complete||!atlas.naturalWidth)return false;const index=illustratedActivities.indexOf(view.id);if(index<0)return false;const c=view.ctx,r=view.canvas.getBoundingClientRect(),s=view.scene,t=s.time,age=t-view.lastHit,hit=Math.max(0,1-age/.65);view.scale=Math.min(r.width/700,r.height/950);view.ox=r.width/2-450*view.scale;view.oy=r.height/2-475*view.scale;const bg=c.createLinearGradient(0,0,0,r.height);bg.addColorStop(0,'#fff4d5');bg.addColorStop(1,'#c7d8ad');c.fillStyle=bg;c.fillRect(0,0,r.width,r.height);c.save();c.translate(view.ox,view.oy);c.scale(view.scale,view.scale);const cw=atlas.naturalWidth/5,ch=atlas.naturalHeight/4;s.rounded(116,215,668,480,30,'#fff7df','#d4b77c');c.save();c.beginPath();c.roundRect(130,230,640,450,22);c.clip();c.drawImage(atlas,(index%5)*cw+3,Math.floor(index/5)*ch+3,cw-6,ch-6,130-hit*3,230-hit*3,640+hit*6,450+hit*6);c.restore();s.text('✦ Mỗi thao tác là một điều nhỏ tốt lành ✦',450,175,22,'#536f45');s.character({...view.player,x:450,y:860,name:'',preview:true,action:view.id,animationStarted:Date.now()-age*1000},false);if(hit>0){s.text('+1 XP',650,755-age*40,35,'#49794c');for(let i=0;i<5;i++)s.text('✦',240+i*100,690-age*70,18,'#bf914d');}c.restore();return true;}
